import{_ as p,a0 as r,w as o,s as d,ao as l,I as n,x as s,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"用 fastjar 和 gjar 构建一个 JAR 文件 | LCTT x X-CMD","titleTemplate":false,"description":"用 fastjar 和 gjar 构建一个 JAR 文件 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 fastjar 和 gjar 构建一个 JAR 文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 fastjar 和 gjar 构建一个 JAR 文件 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210818 Build a JAR file with fastjar and gjar","title":"用 fastjar 和 gjar 构建一个 JAR 文件","tag":"202108","desc":""},"relativePath":"202108/20210818 Build a JAR file with fastjar and gjar.md","filePath":"[post].md"}'),h={name:"202108/20210818 Build a JAR file with fastjar and gjar.md"};function g(u,a,f,k,c,b){const i=r("Link");return o(),d("div",null,[a[24]||(a[24]=l(`<h1 id="用-fastjar-和-gjar-构建一个-jar-文件" tabindex="-1">用 fastjar 和 gjar 构建一个 JAR 文件 <a class="header-anchor" href="#用-fastjar-和-gjar-构建一个-jar-文件" aria-label="Permalink to “用 fastjar 和 gjar 构建一个 JAR 文件”">​</a></h1><blockquote><p>fastjar、gjar 和 jar 等工具可以帮助你手动或以编程方式构建 JAR 文件，而其他工具链，如 Maven 和 Gradle 提供了依赖性管理的功能。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202108/27/105207oj4f44t4vbkkv4iq.jpg" alt=""></p><p>根据我的经验，Java 的许多优点之一是它能够以整齐方便的包（称为 JAR，或 Java 归档）来提供应用程序。JAR 文件使用户很容易下载并启动他们想尝试的应用，很容易将该应用从一台计算机转移到另一台计算机（而且 Java 是跨平台的，所以可以鼓励自由分享），而且对于新的程序员来说，查看 JAR 文件的内容，以找出使 Java 应用运行的原因是很容易理解的。</p><p>创建 JAR 文件的方法有很多，包括 Maven 和 Gradle 等工具链解决方案，以及 IDE 中的一键构建功能。然而，也有一些独立的命令，如 <code>jarfast</code>、<code>gjar</code> 和普通的 <code>jar</code>，它们对于快速和简单的构建是很有用的，并且可以演示 JAR 文件运行所需要的东西。</p><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3><p>在 Linux 上，你可能已经有了 <code>fastjar</code>、<code>gjar</code> 或作为 OpenJDK 包或 GCJ（GCC-Java）的一部分的 <code>jar</code> 命令。你可以通过输入不带参数的命令来测试这些命令是否已经安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fastjar</span></span>
<span class="line"><span>Try &#39;fastjar --help&#39; for more information.</span></span>
<span class="line"><span>$ gjar</span></span>
<span class="line"><span>jar: must specify one of -t, -c, -u, -x, or -i</span></span>
<span class="line"><span>jar: Try &#39;jar --help&#39; for more information</span></span>
<span class="line"><span>$ jar</span></span>
<span class="line"><span>Usage: jar [OPTION...] [ [--release VERSION] [-C dir] files] ...</span></span>
<span class="line"><span>Try \`jar --help&#39; for more information.</span></span></code></pre></div><p>我安装了所有这些命令，但你只需要一个。所有这些命令都能够构建一个 JAR。</p><p>在 Fedora 等现代 Linux 系统上，输入一个缺失的命令你的操作系统提示安装它。</p>`,10)),n("p",null,[a[2]||(a[2]=s("另外，你可以直接从 ",-1)),e(i,{href:"https://adoptopenjdk.net/"},{default:t(()=>[...a[0]||(a[0]=[s("AdoptOpenJDK.net",-1)])]),_:1}),a[3]||(a[3]=s(" 为 Linux、MacOS 和 Windows ",-1)),e(i,{href:"https://opensource.com/article/19/11/install-java-linux"},{default:t(()=>[...a[1]||(a[1]=[s("安装 Java",-1)])]),_:1}),a[4]||(a[4]=s("。",-1))]),a[25]||(a[25]=l(`<h3 id="构建-jar" tabindex="-1">构建 JAR <a class="header-anchor" href="#构建-jar" aria-label="Permalink to “构建 JAR”">​</a></h3><p>首先，你需要构建一个 Java 应用。</p><p>为了简单起见，在一个名为 <code>hello.java</code> 的文件中创建一个基本的 “hello world” 应用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class Main {</span></span>
<span class="line"><span>public static void main(String[] args) {</span></span>
<span class="line"><span>    System.out.println(&quot;Hello Java World&quot;);</span></span>
<span class="line"><span>}}</span></span></code></pre></div><p>这是一个简单的应用，在某种程度上淡化了管理外部依赖关系在现实世界中的重要性。不过，这也足以让你开始了解创建 JAR 所需的基本概念了。</p><p>接下来，创建一个清单文件。清单文件描述了 JAR 的 Java 环境。在这个例子里，最重要的信息是识别主类，这样执行 JAR 的 Java 运行时就知道在哪里可以找到应用的入口点。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mdir META-INF</span></span>
<span class="line"><span>$ echo &quot;Main-Class: Main&quot; &gt; META-INF/MANIFEST.MF</span></span></code></pre></div><h3 id="编译-java-字节码" tabindex="-1">编译 Java 字节码 <a class="header-anchor" href="#编译-java-字节码" aria-label="Permalink to “编译 Java 字节码”">​</a></h3><p>接下来，把你的 Java 文件编译成 Java 字节码。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ javac hello.java</span></span></code></pre></div><p>另外，你也可以使用 GCC 的 Java 组件来编译：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gcj -C hello.java</span></span></code></pre></div><p>无论哪种方式，都会产生文件 <code>Main.class</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file Main.class</span></span>
<span class="line"><span>Main.class: compiled Java class data, version XX.Y</span></span></code></pre></div><h3 id="创建-jar" tabindex="-1">创建 JAR <a class="header-anchor" href="#创建-jar" aria-label="Permalink to “创建 JAR”">​</a></h3><p>你有了所有需要的组件，这样你就可以创建 JAR 文件了。</p><p>我经常包含 Java 源码给好奇的用户参考，这只需 <code>META-INF</code> 目录和类文件即可。</p>`,17)),n("p",null,[a[6]||(a[6]=n("code",null,"fastjar",-1)),a[7]||(a[7]=s(" 命令使用类似于 ",-1)),e(i,{href:"https://opensource.com/article/17/7/how-unzip-targz-file"},{default:t(()=>[...a[5]||(a[5]=[s("tar 命令",-1)])]),_:1}),a[8]||(a[8]=s("的语法。",-1))]),a[26]||(a[26]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fastjar cvf hello.jar META-INF Main.class</span></span></code></pre></div><p>另外，你也可以用 <code>gjar</code>，方法大致相同，只是 <code>gjar</code> 需要你明确指定清单文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gjar cvf world.jar Main.class -m META-INF/MANIFEST.MF</span></span></code></pre></div><p>或者你可以使用 <code>jar</code> 命令。注意这个命令不需要清单文件，因为它会自动为你生成一个，但为了安全起见，我明确定义了主类：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ jar --create --file hello.jar --main-class=Main Main.class</span></span></code></pre></div><p>测试你的应用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java -jar hello.jar</span></span>
<span class="line"><span>Hello Java World</span></span></code></pre></div><h3 id="轻松打包" tabindex="-1">轻松打包 <a class="header-anchor" href="#轻松打包" aria-label="Permalink to “轻松打包”">​</a></h3><p>像 <code>fastjar</code>、<code>gjar</code> 和 <code>jar</code> 这样的工具可以帮助你手动或以编程方式构建 JAR 文件，而其他工具链如 Maven 和 Gradle 则提供了依赖性管理的功能。一个好的 IDE 可能会集成这些功能中的一个或多个。</p><p>无论你使用什么解决方案，Java 都为分发你的应用代码提供了一个简单而统一的目标。</p><hr>`,11)),n("p",null,[a[10]||(a[10]=s("via: ",-1)),e(i,{href:"https://opensource.com/article/21/8/fastjar"},{default:t(()=>[...a[9]||(a[9]=[s("https://opensource.com/article/21/8/fastjar",-1)])]),_:1})]),n("p",null,[a[15]||(a[15]=s("作者：",-1)),e(i,{href:"https://opensource.com/users/seth"},{default:t(()=>[...a[11]||(a[11]=[s("Seth Kenlon",-1)])]),_:1}),a[16]||(a[16]=s(" 选题：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...a[12]||(a[12]=[s("lujun9972",-1)])]),_:1}),a[17]||(a[17]=s(" 译者：",-1)),e(i,{href:"https://github.com/geekpi"},{default:t(()=>[...a[13]||(a[13]=[s("geekpi",-1)])]),_:1}),a[18]||(a[18]=s(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:t(()=>[...a[14]||(a[14]=[s("wxy",-1)])]),_:1})]),n("p",null,[a[21]||(a[21]=s("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...a[19]||(a[19]=[s("LCTT",-1)])]),_:1}),a[22]||(a[22]=s(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...a[20]||(a[20]=[s("Linux中国",-1)])]),_:1}),a[23]||(a[23]=s(" 荣誉推出",-1))])])}const J=p(h,[["render",g]]);export{v as __pageData,J as default};
